-- V5: the sample design of github-repos and the metadata of the published data snapshots (issue #58).
--
-- core.sample_population and core.sample_windows hold docs/data/population-by-month.csv and
-- docs/data/sample-windows.csv as written by run 19 of github-repos (2026-11-18, --seed=42 --limit=5000
-- --min-stars=10, 2018-01-01..2025-12-31), the run behind release data-repos-2026-11-19. With them the
-- sample is in the database: a repository is in the sample when its created_at falls into a window.
-- SampleDesignIT checks that the rows below equal the two CSV files.
--
-- core.data_snapshots says when each published release was collected. Weekly series end with the
-- partial week of collection; views take that week from here, not from the run journal, which
-- data-only dumps do not carry. A local collection adds its own row (see the table comment).

CREATE TABLE core.sample_population (
    month date PRIMARY KEY CHECK (extract(day FROM month) = 1),
    population integer NOT NULL CHECK (population > 0)
);

CREATE TABLE core.sample_windows (
    window_from timestamptz PRIMARY KEY,
    window_to timestamptz NOT NULL CHECK (window_to > window_from),
    month date NOT NULL REFERENCES core.sample_population (month),
    repos integer NOT NULL CHECK (repos >= 0),
    taken integer NOT NULL UNIQUE CHECK (taken > 0),
    window_period tstzrange GENERATED ALWAYS AS (tstzrange(window_from, window_to, '[]')) STORED,
    EXCLUDE USING gist (window_period WITH &&)
);

CREATE TABLE core.data_snapshots (
    release text PRIMARY KEY CHECK (release <> ''),
    source text NOT NULL CHECK (source <> ''),
    collected_from timestamptz NOT NULL,
    collected_to timestamptz NOT NULL CHECK (collected_to >= collected_from),
    collection_week date NULL CHECK (extract(isodow FROM collection_week) = 7),
    note text NULL
);

COMMENT ON TABLE core.sample_population IS
    'Население страт выборки github-repos: репозитории с stars >= 10, созданные в месяце, на начало запуска 19 (18.11.2026)';
COMMENT ON TABLE core.sample_windows IS
    'Окна выборки github-repos (запуск 19, seed 42): репозиторий в выборке, если created_at попадает в окно (обе границы включены)';
COMMENT ON COLUMN core.sample_windows.repos IS 'Репозитории окна на момент сбора; 0 - окно взято, но подходящих репозиториев в нём нет';
COMMENT ON COLUMN core.sample_windows.taken IS 'Порядок взятия окон, как в sample-windows.csv';
COMMENT ON COLUMN core.sample_windows.window_period IS 'Окно как диапазон [window_from, window_to] для соединения по created_at';
COMMENT ON TABLE core.data_snapshots IS
    'Когда собран каждый опубликованный релиз данных; локальный сбор добавляет свою строку с release = local-<дата>';
COMMENT ON COLUMN core.data_snapshots.collection_week IS
    'Воскресенье недели сбора недельных рядов: эта неделя в данных неполная';



